window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-27501\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονώψ,</h1><div class=\"entry-meta\"><span>DGP · ordem 1922 na letra μ · nº geral 27501</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. μουνώψ, ῶπος (masc., fem.) que tem apenas um olho. 〈μόνος, ὤψ〉</p></section></article>\n<article id=\"entry-dgp-27502\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μόνωψ, ωπος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1923 na letra μ · nº geral 27502</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">touro selvagem; bisão.</p></section></article>\n<article id=\"entry-dgp-27503\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μόρα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1924 na letra μ · nº geral 27503</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór., na Lacedemônia, corpo de infantaria.</p></section></article>\n<article id=\"entry-dgp-27504\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μόρε</h1><div class=\"entry-meta\"><span>DGP · ordem 1925 na letra μ · nº geral 27504</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">poét. = ἔμμορε.</p></section></article>\n<article id=\"entry-dgp-27505\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μορία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1926 na letra μ · nº geral 27505</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ger. pl. oliveira sagrada.</p></section></article>\n<article id=\"entry-dgp-27506\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μόριμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1927 na letra μ · nº geral 27506</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">μόρσιμος.</p></section></article>\n<article id=\"entry-dgp-27507\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μόριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1928 na letra μ · nº geral 27507</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 parte; porção 2 parte do corpo; membro 3 pl. partes sexuais; genitália (dos humanos e dos animais) 4 Filos. parte constitutiva; elemento essencial 5 Matem. fração. 〈μόρος〉</p></section></article>\n<article id=\"entry-dgp-27508\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μόριος Ζεύς (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1929 na letra μ · nº geral 27508</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Zeus protetor das oliveiras sagradas. 〈μορία〉</p></section></article>\n<article id=\"entry-dgp-27509\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μορμολυκεῖον</h1><div class=\"entry-meta\"><span>DGP · ordem 1930 na letra μ · nº geral 27509</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e μορμολύκειον, ου (τό) boneco para amedrontar as crianças; espantalho. 〈μορμολύττω〉</p></section></article>\n<article id=\"entry-dgp-27510\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μορμολύττω</h1><div class=\"entry-meta\"><span>DGP · ordem 1931 na letra μ · nº geral 27510</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 assustar com um espantalho ♦ méd. (só pres., impf. e aor.) 2 assustar alguém, ac., para desviá-lo de, ἀπό e gen. ♦ pas. 3 assustar-se com, ac. 〈μορμώ〉</p></section></article>\n<article id=\"entry-dgp-27511\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μορμύρω</h1><div class=\"entry-meta\"><span>DGP · ordem 1932 na letra μ · nº geral 27511</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">onomat., at. e méd. murmurar borbulhando; murmurar; rumorejar.</p></section></article>\n<article id=\"entry-dgp-27512\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μορμώ, όος-οῦς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1933 na letra μ · nº geral 27512</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">figura de mulher que faz caretas, espécie de bruxa que assusta as crianças.</p></section></article>\n<article id=\"entry-dgp-27513\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μορμών, ονος</h1><div class=\"entry-meta\"><span>DGP · ordem 1934 na letra μ · nº geral 27513</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ῶνος (ἡ) = μορμώ.</p></section></article>\n<article id=\"entry-dgp-27514\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μορόεις, όεσσα, όεν</h1><div class=\"entry-meta\"><span>DGP · ordem 1935 na letra μ · nº geral 27514</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">penosamente elaborado; artisticamente trabalhado; precioso. 〈μόρος〉</p></section></article>\n<article id=\"entry-dgp-27515\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μόρον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1936 na letra μ · nº geral 27515</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">amora.</p></section></article>\n<article id=\"entry-dgp-27516\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μόρος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1937 na letra μ · nº geral 27516</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 parte atribuída aos homens pelo destino; sorte; destino 2 infortúnio; desgraça; destino funesto 3 morte violenta; morte 4 cadáver ♦ ὁ Μόρος 5 Destino, person. 〈μείρομαι〉</p></section></article>\n<article id=\"entry-dgp-27517\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μόρσιμος, ος</h1><div class=\"entry-meta\"><span>DGP · ordem 1938 na letra μ · nº geral 27517</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e η, ον 1 marcado pelo destino; fatal: μόρσιμόν ἐστι hom. está destinado ou é fatal que, inf. 2 marcado pelo destino para a morte: μόρσιμον ἦμαρ hom. dia fatal 3 exposto à morte; mortal: οὔτοι μόρσιμός εἰμι hom. não sou sujeito à morte ♦ ὁ Μόρσιμος 4 Mórsimo, n. de h. ♦ τὸ μόρσιμον 5 o destino; o inevitável.</p></section></article>\n<article id=\"entry-dgp-27518\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μορύσσω</h1><div class=\"entry-meta\"><span>DGP · ordem 1939 na letra μ · nº geral 27518</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só aor. at. ἐμόρυξα e perf. pas. μεμορυγμένος) 1 escurecer; manchar; sujar 2 tingir de uma cor escura.</p></section></article>\n<article id=\"entry-dgp-27519\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μορφά</h1><div class=\"entry-meta\"><span>DGP · ordem 1940 na letra μ · nº geral 27519</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = μορφή.</p></section></article>\n<article id=\"entry-dgp-27520\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μορφάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1941 na letra μ · nº geral 27520</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 contrafazer; imitar; falsificar, ac. 2 fazer caretas; fazer trejeitos; gesticular. 〈μορφή〉</p></section></article>\n<article id=\"entry-dgp-27521\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μορφή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1942 na letra μ · nº geral 27521</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 forma; figura; aspecto 2 forma do corpo; talhe; estatura 3 forma aparente; aparência (de sonhos, de fantasmas), op. a εἶδος “forma real”: ὀνειράτων ἀλίγκιοι μορφαῖσι ésql. semelhantes às formas de sonhos 4 espécie; sorte; gênero: ἄλλαι βιότου μορφαί eur. outra espécie de vida 5 crist. natureza ou essência de Deus.</p></section></article>\n<article id=\"entry-dgp-27522\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μόρφνος, ης, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1943 na letra μ · nº geral 27522</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de cor escura; enegrecido; negro.</p></section></article>\n<article id=\"entry-dgp-27523\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μορφοειδής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1944 na letra μ · nº geral 27523</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Filos. que tem uma forma; formal: τὰ μὴ ἔχοντα μορφοειδῆ σχηματισμόν ep. as coisas que não possuem uma forma precisa. 〈μορφή, εἶδος〉</p></section></article>\n<article id=\"entry-dgp-27524\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μορφόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1945 na letra μ · nº geral 27524</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 dar uma forma a; figurar; representar, ac. ♦ pas. 2 tomar forma. 〈μορφή〉</p></section></article>\n<article id=\"entry-dgp-27525\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μόρφωμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1946 na letra μ · nº geral 27525</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">forma; figura; exterior; aspecto: ὀνεί­ρων προσφερεῖς μορφωμάσιν ésql. semelhantes a formas de sonhos. 〈μορφόω〉</p></section></article>\n<article id=\"entry-dgp-27526\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μόρφωσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1947 na letra μ · nº geral 27526</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de dar forma a; formulação 2 bíbl. forma exterior; aparência; figura. 〈μορφόω〉</p></section></article>\n<article id=\"entry-dgp-27527\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μόσσυν</h1><div class=\"entry-meta\"><span>DGP · ordem 1948 na letra μ · nº geral 27527</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e μόσυν, υνος (ὁ) 1 torno de madeira 2 cabana; barraca de madeira 3 construção de madeira (paliçada, navio).</p></section></article>\n<article id=\"entry-dgp-27528\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μοσσύνοικοι</h1><div class=\"entry-meta\"><span>DGP · ordem 1949 na letra μ · nº geral 27528</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e Μοσύνοικοι, ων (οἱ) os mossinecos, povo do Ponto e da Cítia, que habitavam casas de madeira. 〈μόσσυν, οἰκέω〉</p></section></article>\n<article id=\"entry-dgp-27529\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μόσυν, υνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1950 na letra μ · nº geral 27529</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">μόσσυν.</p></section></article>\n<article id=\"entry-dgp-27530\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοσύνοις</h1><div class=\"entry-meta\"><span>DGP · ordem 1951 na letra μ · nº geral 27530</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dat. pl. át. de μόσυν.</p></section></article>\n<article id=\"entry-dgp-27531\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μόσχειος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1952 na letra μ · nº geral 27531</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de vitelo. 〈μόσχος〉</p></section></article>\n<article id=\"entry-dgp-27532\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοσχοποιέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1953 na letra μ · nº geral 27532</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. fabricar a imagem de um bezerro. 〈μόσχος, ποιέω〉</p></section></article>\n<article id=\"entry-dgp-27533\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μόσχος, ου (ὁ, ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1954 na letra μ · nº geral 27533</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 broto de planta; rebento 2 pimpolho; guri 3 filhote de animal, de pássaro 4 vitelo; novilha 5 aroma almiscarado ♦ ὁ Μόσχος 6 Mosco, poeta bucólico.</p></section></article>\n<article id=\"entry-dgp-27534\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοτός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1955 na letra μ · nº geral 27534</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Medic. 1 faixa de linho para curativo; venda; tampão 2 tubo de drenagem; sonda cirúrgica.</p></section></article>\n<article id=\"entry-dgp-27535\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοῦ</h1><div class=\"entry-meta\"><span>DGP · ordem 1956 na letra μ · nº geral 27535</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. de ἐγώ.</p></section></article>\n<article id=\"entry-dgp-27536\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μουνάξ</h1><div class=\"entry-meta\"><span>DGP · ordem 1957 na letra μ · nº geral 27536</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv., jôn. isoladamente. 〈μόνος〉</p></section></article>\n<article id=\"entry-dgp-27537\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μουναρχέω, μουναρχίη, μούναρχος</h1><div class=\"entry-meta\"><span>DGP · ordem 1958 na letra μ · nº geral 27537</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = μοναρχέω, μο­ναρχία, μόναρχος.</p></section></article>\n<article id=\"entry-dgp-27538\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μουνιχία</h1><div class=\"entry-meta\"><span>DGP · ordem 1959 na letra μ · nº geral 27538</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e Μουνυχία, ας (ἡ) 1 Muníquia, península e por­to de Atenas 2 a deusa de Muníquia, Ártemis ou Hé­cate. 〈Μούνιχος〉</p></section></article>\n<article id=\"entry-dgp-27539\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μουνιχίαζε</h1><div class=\"entry-meta\"><span>DGP · ordem 1960 na letra μ · nº geral 27539</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e Μουνυχίαζε adv. em direção a Muníquia. 〈Μου­νιχία, -ζε〉</p></section></article>\n<article id=\"entry-dgp-27540\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μουνιχίασι</h1><div class=\"entry-meta\"><span>DGP · ordem 1961 na letra μ · nº geral 27540</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e Μουνυχίασι adv. em Muníquia. 〈Μουνιχία〉</p></section></article>\n<article id=\"entry-dgp-27541\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μουνιχιών</h1><div class=\"entry-meta\"><span>DGP · ordem 1962 na letra μ · nº geral 27541</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e Μουνυχιών, ῶνος (ὁ) Muníquion, 10º mês do calendário ático (corresp. à 2ª quinzena de abril e 1ª quinzena de maio).</p></section></article>\n<article id=\"entry-dgp-27542\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μούνιχος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1963 na letra μ · nº geral 27542</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Munico, antigo rei de Muníquia.</p></section></article>\n<article id=\"entry-dgp-27543\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μουνογένης, μουνόκωλος, μουνόλιθος</h1><div class=\"entry-meta\"><span>DGP · ordem 1964 na letra μ · nº geral 27543</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = μονογε­νής, μονόκωλος, μονόλιθος.</p></section></article>\n<article id=\"entry-dgp-27544\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοῦνος, μουνόω</h1><div class=\"entry-meta\"><span>DGP · ordem 1965 na letra μ · nº geral 27544</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = μόνος, μονόω.</p></section></article>\n<article id=\"entry-dgp-27545\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μουνυχία, Μουνυχίαζε</h1><div class=\"entry-meta\"><span>DGP · ordem 1966 na letra μ · nº geral 27545</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Μουνιχία, Μουνιχίαζε.</p></section></article>\n<article id=\"entry-dgp-27546\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μουνώψ</h1><div class=\"entry-meta\"><span>DGP · ordem 1967 na letra μ · nº geral 27546</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">μονώψ.</p></section></article>\n<article id=\"entry-dgp-27547\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μοῦσα, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1968 na letra μ · nº geral 27547</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 Musa 2 pl. as Musas, filhas de Zeus e de Mnemosine, deusas das artes e das ciências 3 ciência; arte 4 música; canto; poesia 5 cultura; educação.</p></section></article>\n<article id=\"entry-dgp-27548\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μουσαῖος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1969 na letra μ · nº geral 27548</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 concernente às Musas ♦ ὁ Μουσαῖος 1 Museu, poeta. 〈μοῦσα〉</p></section></article>\n<article id=\"entry-dgp-27549\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μουσεῖον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1970 na letra μ · nº geral 27549</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 templo das Musas; morada das Musas 2 lugar de prática da poesia, artes etc.; escola 3 escola filosófica; biblioteca; museu 4 obra das musas; canto poético ♦ τὰ μουσεῖα 5 festa das Musas. 〈Μοῦσα〉</p></section></article>\n<article id=\"entry-dgp-27550\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μουσηγέτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1971 na letra μ · nº geral 27550</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">guia das Musas, Apolo. 〈Μοῦσα, ἡγέομαι〉</p></section></article>\n<article id=\"entry-dgp-27551\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μουσικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1972 na letra μ · nº geral 27551</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que concerne às Musas, à poesia ou às artes 2 musical; canoro: θέαι μουσικαί plut. espetáculos musicais 3 que cultiva a música; músico (pessoa) 4 instruído; educado; douto 5 hábil em, inf. 6 delicado (alimentos) ♦ ἡ μουσική 7 a música; canto lírico 8 educação literária e artística 9 habilidade; destreza ♦ τὰ μουσικά 10 a música. 〈Μοῦσα〉</p></section></article>\n<article id=\"entry-dgp-27552\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μουσικῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 1973 na letra μ · nº geral 27552</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 segundo as regras da música; musicalmente 2 com arte; com gosto; convenientemente.</p></section></article>\n<article id=\"entry-dgp-27553\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μουσόληπτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1974 na letra μ · nº geral 27553</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">possuído ou inspirado pelas Musas. 〈Μοῦσα, ληπτός〉</p></section></article>\n<article id=\"entry-dgp-27554\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μουσομανέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1975 na letra μ · nº geral 27554</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ser cultor das artes, da poesia, da música. 〈μουσομανής〉</p></section></article>\n<article id=\"entry-dgp-27555\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μουσομανής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1976 na letra μ · nº geral 27555</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inspirado pelas Musas; apaixonado pelas artes, pela poesia, pela música. 〈Μοῦσα, μαίνομαι〉</p></section></article>\n<article id=\"entry-dgp-27556\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μουσομανία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1977 na letra μ · nº geral 27556</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">paixão pelas artes, pela poesia, pela música. 〈μουσομανής〉</p></section></article>\n<article id=\"entry-dgp-27557\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μουσομήτωρ, ορος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1978 na letra μ · nº geral 27557</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">mãe das Musas. 〈Μοῦσα, μήτηρ〉</p></section></article>\n<article id=\"entry-dgp-27558\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μουσοποιός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1979 na letra μ · nº geral 27558</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) 1 que canta em versos ♦ ὁ μουσοποιός 2 poeta 3 poeta lírico. 〈Μοῦσα, ποιέω〉</p></section></article>\n<article id=\"entry-dgp-27559\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μουσοπόλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1980 na letra μ · nº geral 27559</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que cultiva as Musas; poético; melodioso ♦ ὁ μουσοπόλος 2 poeta. 〈Μοῦσα, πολέω〉</p></section></article>\n<article id=\"entry-dgp-27560\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μουσουργία,</h1><div class=\"entry-meta\"><span>DGP · ordem 1981 na letra μ · nº geral 27560</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. μουσουργίη, ης (ἡ) canto; poesia. 〈μου­σουργός〉</p></section></article>\n<article id=\"entry-dgp-27561\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μουσουργός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1982 na letra μ · nº geral 27561</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que cultiva a música ♦ ὁ, ἡ μουσουρ­γός 2 cantor; cantora. 〈Μοῦσα, ἔργον〉</p></section></article>\n<article id=\"entry-dgp-27562\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μουσόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1983 na letra μ · nº geral 27562</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 dotar de voz harmoniosa 2 instruir segundo as regras da arte ♦ pas. 3 ser exercitado na arte; part. perf. μεμουσωμένος plut. educado; de gosto refinado. 〈Μοῦσα〉</p></section></article>\n<article id=\"entry-dgp-27563\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοὖστι</h1><div class=\"entry-meta\"><span>DGP · ordem 1984 na letra μ · nº geral 27563</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e μοὔστι crase poét. de μοῦ ἐστι e μοί ἐστι.</p></section></article>\n<article id=\"entry-dgp-27564\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοχθέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1985 na letra μ · nº geral 27564</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 dar-se uma tarefa; trabalhar; fatigar-se por alguém, περί e ac. 2 sofrer; padecer por causa de algo, dat. 3 enfrentar ou suportar com sofrimento fadigas, trabalhos, dores, dificuldades 4 cuidar com desvelo de, ac. 〈μόχθος〉</p></section></article>\n<article id=\"entry-dgp-27565\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μόχθημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1986 na letra μ · nº geral 27565</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ger. pl. trabalho; sofrimento; fadiga; dificuldade. 〈μοχθέω〉</p></section></article>\n<article id=\"entry-dgp-27566\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοχθηρία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1987 na letra μ · nº geral 27566</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 estado de penúria; miséria 2 má qualidade; insalubridade (de um lugar); mal cheiro 3 perversidade; maldade 4 erro; vício (de argumentação). 〈μοχθηρός〉</p></section></article>\n<article id=\"entry-dgp-27567\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοχθηρός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1988 na letra μ · nº geral 27567</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que comporta penas ou fadigas; sofrido; doloroso 2 que suporta pacientemente uma provação; resignado; conformado 3 de má qualidade; maldoso; perverso 4 falaz; viciado; errôneo (argumento). 〈μόχθος〉</p></section></article>\n<article id=\"entry-dgp-27568\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοχθηρῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 1989 na letra μ · nº geral 27568</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 penosamente 2 maldosamente.</p></section></article>\n<article id=\"entry-dgp-27569\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοχθίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1990 na letra μ · nº geral 27569</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) 1 fatigar-se por algo, περί e dat. 2 sofrer por causa de algo, ac. ou dat. 〈μόχθος〉</p></section></article>\n<article id=\"entry-dgp-27570\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μόχθος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1991 na letra μ · nº geral 27570</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pena; trabalho; fadiga; sofrimento; dor.</p></section></article>\n<article id=\"entry-dgp-27571\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοχλεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1992 na letra μ · nº geral 27571</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">levantar ou deslocar com uma alavanca. 〈μοχλός〉</p></section></article>\n<article id=\"entry-dgp-27572\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοχλέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1993 na letra μ · nº geral 27572</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">μοχλεύω.</p></section></article>\n<article id=\"entry-dgp-27573\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοχλίον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1994 na letra μ · nº geral 27573</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">alavanca pequena. 〈μοχλός〉</p></section></article>\n<article id=\"entry-dgp-27574\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοχλός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1995 na letra μ · nº geral 27574</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 alavanca para deslocar um navio, para forçar uma porta 2 estaca 3 ferrolho para porta: τὸν μοχλὸν ἐμβάλλειν xen. passar o ferrolho, πύλας μοχλοῖς χαλᾶν ésql. baixar os ferrolhos e abrir a porta.</p></section></article>\n<article id=\"entry-dgp-27575\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μῦ (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1996 na letra μ · nº geral 27575</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">indecl., mi, letra do alfabeto grego.</p></section></article>\n<article id=\"entry-dgp-27576\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυγαλέη-ῆ, έης-ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1997 na letra μ · nº geral 27576</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">musaranho, mamífero insetívoro. 〈μῦς, γαλέη〉</p></section></article>\n<article id=\"entry-dgp-27577\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μυγδονία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1998 na letra μ · nº geral 27577</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Migdônia, região da Macedônia.</p></section></article>\n<article id=\"entry-dgp-27578\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μυγδονικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1999 na letra μ · nº geral 27578</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Μυγδόνιος.</p></section></article>\n<article id=\"entry-dgp-27579\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μυγδόνιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2000 na letra μ · nº geral 27579</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de Mignônia; migdônio.</p></section></article>\n<article id=\"entry-dgp-27580\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυδαλέος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2001 na letra μ · nº geral 27580</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">úmido; banhado de, dat. 〈μύδος〉</p></section></article>\n<article id=\"entry-dgp-27581\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυδάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2002 na letra μ · nº geral 27581</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 estar úmido, molhado 2 destilar; gotejar 3 em­bolorar ou tornar-se podre por causa da umidade. 〈μύδος〉</p></section></article>\n<article id=\"entry-dgp-27582\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μύδησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2003 na letra μ · nº geral 27582</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 o estado de úmido, de viscoso, de purulento 2 putrefação. 〈μυδάω〉</p></section></article>\n<article id=\"entry-dgp-27583\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μῦδος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2004 na letra μ · nº geral 27583</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bolor; mofo.</p></section></article>\n<article id=\"entry-dgp-27584\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυδροκτυπέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2005 na letra μ · nº geral 27584</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bater o ferro incandescente. 〈μύδρος, κτύπος〉</p></section></article>\n<article id=\"entry-dgp-27585\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μύδρος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2006 na letra μ · nº geral 27585</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">massa de ferro incandescente.</p></section></article>\n<article id=\"entry-dgp-27586\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μυεκφορίτης νόμος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2007 na letra μ · nº geral 27586</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">o nomo Miecforites, no Egito. 〈μῦς, ἐκφορέω〉</p></section></article>\n<article id=\"entry-dgp-27587\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυελόεις, όεσσα, όεν</h1><div class=\"entry-meta\"><span>DGP · ordem 2008 na letra μ · nº geral 27587</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cheio de tutano, de miolo. 〈μυελός〉</p></section></article>\n<article id=\"entry-dgp-27588\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυελός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2009 na letra μ · nº geral 27588</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tutano; medula 2 miolo; cerne de árvore 3 qualquer substância nutritiva ou fortificante 4 a parte mais interna; o íntimo.</p></section></article>\n<article id=\"entry-dgp-27589\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2010 na letra μ · nº geral 27589</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. μυήσω, aor. ἐμύησα, perf. μεμύηκα) 1 iniciar nos mistérios, ac. 2 iniciar em uma ciência, em uma arte; ensinar; instruir; preparar ♦ pas. 3 ser iniciado em, ac.: μυεῖσθαι τὰ μεγάλα [μυστήρια] ar. ser iniciado nos grandes mistérios, μυεῖσθαι τῆς Ἀφροδίτης hel. ser iniciado nos mistérios de Afrodite 4 ser instruído para, inf.</p></section></article>\n<article id=\"entry-dgp-27590\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μύζω</h1><div class=\"entry-meta\"><span>DGP · ordem 2011 na letra μ · nº geral 27590</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἔμυζον, fut. μύξω, aor. ἔμυξα, perf. desus.) 1 fazer “mu” fechando os lábios 2 gemer; grunhir; murmurar; resmungar 3 sugar.</p></section></article>\n<article id=\"entry-dgp-27591\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μύησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2012 na letra μ · nº geral 27591</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 iniciação nos preceitos de uma religião 2 crist. mistério; revelação. 〈μυέω〉</p></section></article>\n<article id=\"entry-dgp-27592\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυθάριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2013 na letra μ · nº geral 27592</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">historieta; pequena narrativa</p></section></article>\n<article id=\"entry-dgp-27593\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 2014⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 2014 na letra μ · nº geral 27593</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">. 〈μῦθος〉 μυθέαι e μυθεῖαι (contr. de μυθέεαι) 2ª sing. pres. ind. poét. de μυθέομαι.</p></section></article>\n<article id=\"entry-dgp-27594\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυθέομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 2015 na letra μ · nº geral 27594</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. μυθέω.</p></section></article>\n<article id=\"entry-dgp-27595\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυθέσκοντο</h1><div class=\"entry-meta\"><span>DGP · ordem 2016 na letra μ · nº geral 27595</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. impf. iter. de μυθέω.</p></section></article>\n<article id=\"entry-dgp-27596\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μύθευμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2017 na letra μ · nº geral 27596</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">conto; narrativa</p></section></article>\n<article id=\"entry-dgp-27597\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 2018⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 2018 na letra μ · nº geral 27597</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">. 〈μυθέυω〉 μυθεῦσαι part. fem. pl. pres. dór. de μυθέομαι.</p></section></article>\n<article id=\"entry-dgp-27598\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυθεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 2019 na letra μ · nº geral 27598</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fazer uma narrativa</p></section></article>\n<article id=\"entry-dgp-27599\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 2020⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 2020 na letra μ · nº geral 27599</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fabulosa 2 contar; narrar. 〈μῦθος〉 μυθέω-ῶ ger. méd. μυθέομαι-οῦμαι 1 falar; conversar 2 dizer; contar algo, ac., a alguém, dat. 3 designar; chamar; nomear 4 anunciar um oráculo 5 ordenar, inf. 6 dizer a si mesmo; deliberar por si mesmo, ac. 〈μῦθος〉</p></section></article>\n<article id=\"entry-dgp-27600\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυθήσεαι</h1><div class=\"entry-meta\"><span>DGP · ordem 2021 na letra μ · nº geral 27600</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª sing. fut. jôn., μυθήσομαι fut. ind. e aor. ép. subj., de μυθέομαι.</p></section></article>\n";
